if (-not (Test-Path "raw_screens")) {
    New-Item -ItemType Directory -Path "raw_screens" | Out-Null
}

foreach ($key in $screens.Keys) {
    Write-Host "Downloading $key..."
    $url = $screens[$key]
    # Remove any extra whitespace from URL
    $url = $url.Trim()
    $outFile = "raw_screens/$key.html"
    try {
        Invoke-RestMethod -Uri $url -OutFile $outFile
        Write-Host "Saved $outFile"
    } catch {
        Write-Error "Failed to download ${key}: $_"
    }
}
